function notify(s){toast.textContent=s;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3500)}
function filters(){const host=$('categoryFilters');host.innerHTML=cats.map(c=>'<button type="button" class="category-filter '+(c===activeCategory?'active':'')+'" data-category="'+esc(c)+'">'+esc(c)+'</button>').join('');host.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category;filters();render()})}
function render(){const q=$('toolSearch').value.trim().toLowerCase();let list=tools.filter(t=>(activeCategory==='All tools'||t.category===activeCategory)&&(!q||(t.name+' '+t.desc+' '+t.category+' '+t.keywords).toLowerCase().includes(q)));const sort=$('sortTools').value;if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));else if(sort==='category')list.sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name));else list.sort((a,b)=>b.featured-a.featured||a.name.localeCompare(b.name));$('searchCount').textContent=list.length+' tools found'+(q?' for “'+$('toolSearch').value.trim()+'”':'')+'.';const grouped={};list.forEach(t=>(grouped[t.category]||(grouped[t.category]=[])).push(t));const order=cats.slice(1).filter(c=>grouped[c]);$('toolDirectory').innerHTML=list.length?order.map(c=>'<section class="category-block" id="category-'+slug(c)+'"><div class="category-head"><h3>'+esc(c)+'</h3><span>'+grouped[c].length+' tools</span></div><div class="tool-cards">'+grouped[c].map(t=>'<article class="directory-card"><div class="card-meta"><span class="tool-glyph">'+esc(t.icon)+'</span><span class="tool-badge">'+esc(t.category)+'</span></div><h4>'+esc(t.name)+'</h4><p>'+esc(t.desc)+'</p><div class="card-actions"><button class="tool-card-link" data-tool="'+t.id+'">'+(t.kind==='link'?'Open file tools ↗':'Use tool →')+'</button><span class="tool-label">Free</span></div></article>').join('')+'</div></section>').join(''):'<div class="empty-state">No matching tools yet. Try another search or <a href="/#request">request this tool</a>.</div>';document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool))}
function area(label,id,placeholder=''){return '<label>'+label+'<textarea id="'+id+'" placeholder="'+esc(placeholder)+'"></textarea></label>'}
function field(label,id,type='number',value='0'){return '<label>'+label+'<input id="'+id+'" type="'+type+'" value="'+esc(value)+'"></label>'}
function buttons(label='Run tool'){return '<div class="tool-controls"><button id="runTool" type="button">'+label+'</button><button id="copyResult" type="button" class="secondary">Copy result</button></div><pre class="tool-output" id="toolOutput"></pre><div class="tool-result" id="toolResult" aria-live="polite"></div>'}
function form(html){return '<div class="tool-form">'+html+'</div>'}
